namespace ghidra.framework.main.projectdata.actions;






using docking.action;
using docking.dnd;
using ghidra.framework.main.datatree;
using ghidra.framework.model;
using ghidra.framework.model;
using ghidra.util;
using ghidra.util;

public class ProjectDataCopyGhidraURLAction : ProjectDataCopyCutBaseAction {

	public ProjectDataCopyGhidraURLAction(string owner, string group) : base("Copy GhidraURL", owner)
    {
		setPopupMenuData(new MenuData(new string[] { "Copy GhidraURL" }, null, group));
		setHelpLocation(new HelpLocation("FrontEndPlugin", "Copy GhidraURL"));
	}

	/* @Override */
	protected void actionPerformed(FrontEndProjectTreeContext context) {

		List<DomainFile> files = context.getSelectedFiles();
		DomainFile df = files.getFirst();
		LinkFileInfo linkInfo = df.getLinkInfo();
		if (linkInfo != null && linkInfo.isFolderLink()) {
			return; // folder-link not supported
		}

		URL url = df.getSharedProjectURL(null);
		if (url == null) {
			url = df.getLocalProjectURL(null);
		}

		if (url == null) {
			Msg.showError(typeof(ProjectDataCopyGhidraURLAction), null,
				"Copy GhidraURL Failed",
				"Failed to create file URL for: " + df.getPathname());
			return;
		}

		try {
			Clipboard clipboard = GClipboard.getSystemClipboard();
			string urlString = url.toString();
			clipboard.setContents(new StringSelection(urlString), null);
		}
		catch (IllegalStateException ise) {
			// this can happen when other applications are accessing the system clipboard
			Msg.showError(typeof(ProjectDataCopyGhidraURLAction), null,
				"Unable to Access Clipboard",
				"Unable to perform cut/copy operation on the system clipboard.  The " +
					"clipboard may just be busy at this time. Please try again.");
		}
	}

	/* @Override */
	protected bool isEnabledForContext(FrontEndProjectTreeContext context) {

		List<DomainFile> files = context.getSelectedFiles();
		if (files.size() != 1) {
			return false;
		}

		DomainFile df = files.getFirst();
		LinkFileInfo linkInfo = df.getLinkInfo();
		if (linkInfo != null && linkInfo.isFolderLink()) {
			return false;
		}
		return true;
	}
}
